H=W=19
orig=[[0]*W for _ in range(H)]
points=[(2,6,3),(3,5,3),(3,6,8),(3,7,3),(4,6,3),(3,13,3),(4,12,3),(4,13,4),(4,14,3),(5,13,3),(9,8,3),(10,7,3),(10,9,3),(11,8,3),(11,14,3),(12,13,3),(12,14,1),(12,15,3),(13,14,3),(13,3,3),(14,2,3),(14,3,2),(14,4,3),(15,3,3)]
for r,c,v in points: orig[r][c]=v
objs=[(3,6,8),(4,13,4),(12,14,1),(14,3,2)]
# crosses arms, including uncolored cross center 10,8
centers=[(r,c) for r,c,v in objs]+[(10,8)]
arm_cells={(r+dr,c+dc) for r,c in centers for dr,dc in [(-1,0),(1,0),(0,-1),(0,1)]}
# only non-source arms are blockers
out=[row[:] for row in orig]
for vertical in [False, True]:
 for r,c,col in objs:
  for dr,dc in ([(0,-1),(0,1)] if not vertical else [(-1,0),(1,0)]):
   rr,cc=r+dr,c+dc
   while 0<=rr<H and 0<=cc<W:
    if (rr,cc) in arm_cells and (rr,cc) not in {(r+ar,c+ac) for ar,ac in [(-1,0),(1,0),(0,-1),(0,1)]}:
     break
    if orig[rr][cc]==0: out[rr][cc]=col
    rr+=dr; cc+=dc
print('\n'.join(' '.join(map(str,row)) for row in out))
